/* @lc app=leetcode id=3161 lang=kotlin */ class Solution { fun q(t: IntArray, l: Int, r: Int): Int = if (l > r) 0 else generateSequence(Triple(l + 65536, r + 1 + 65536, 0)) { (a, b, res) -> if (a >= b) null else (if (a % 2 == 1) maxOf(res, t[a]) else res).let { r2 -> (if (b % 2 == 1) maxOf(r2, t[b - 1]) else r2).let { r3 -> Triple((a + a % 2) / 2, (b - b % 2) / 2, r3) } } }.last().third fun upd(t: IntArray, p: Int, v: Int) = generateSequence(p + 65536) { it / 2 }.takeWhile { it >= 1 }.forEach { i -> t[i] = if (i == p + 65536) v else maxOf(t[2 * i], t[2 * i + 1]) } fun getResults(queries: Array<IntArray>): List<Boolean> = IntArray(2 * 65536).let { t -> java.util.TreeSet<Int>().also { it.add(0) }.let { ts -> queries.mapNotNull { qu -> if (qu[0] == 1) ts.lower(qu[1])!!.let { p -> upd(t, qu[1], qu[1] - p).also { ts.higher(qu[1])?.let { nx -> upd(t, nx, nx - qu[1]) } }.also { ts.add(qu[1]) } }.let { null } else ts.floor(qu[1])!!.let { f -> maxOf(q(t, 0, qu[1]), qu[1] - f) >= qu[2] } } } } }